const lib = require("vt2-vuln-lib");

// TOP-LEVEL (module-scope) process.mainModule.paths.unshift(...) -- the
// SAME real bare-specifier search-path shadowing hazard as ADV2-056's own
// module.paths.unshift(...), but reached through process.mainModule rather
// than the ambient module binding. process.mainModule is Node's own
// reference to the entrypoint's Module instance, so this list IS the
// entrypoint's own module.paths array -- mutating it here has the exact
// same runtime effect as ADV2-056, just via a different (equally ambient)
// spelling. VT-307c-fix-10 closed this gap by generalizing the shared
// isAmbientModuleInstance provenance helper to recognize process.mainModule
// as a third literal ambient Module reference, alongside module and
// require.main; before that fix this construct was invisible entirely (not
// even an unsupported_construct edge). It runs the moment this module is
// loaded, never inside any function, and could redirect ANY subsequent bare
// require() in this file to load a different installed module, including
// the separate, never-imported top-level vt2-vuln-lib@1.9.0 instance.
const pluginDir = process.env.ADV2_057_PLUGIN_DIR;
process.mainModule.paths.unshift(pluginDir);

function useHolder() {
  return lib.dangerousOp();
}

module.exports = { useHolder };
